# Purpose: IF-ELSE statement  — General-purpose PowerShell utilities.
$PROCESSORS   = $ENV:NUMBER_OF_PROCESSORS$COMPUTERNAME = $ENV:COMPUTERNAME if ($PROCESSORS -LT 4) {  write-output "$COMPUTERNAME has $PROCESSORS CPU's."  write-output "You will need to upgrade the number of processors."}elseif ($PROCESSORS -EQ 4){  write-output "$COMPUTERNAME has $PROCESSORS CPU's."  write-output "This is the minimum supported number of processors."}else {  write-output "$COMPUTERNAME has $PROCESSORS CPU's."  write-output "This is an adequate number of processors."}####$logName = "Application"$lastWeek = (get-date).AddDays(-7)$lastweek -= $lastWeek.TimeOfDay$LogErrors = get-eventlog -LogName $logName -EntryType Error -After $lastWeekIf ( $LogErrors.Count -GT 0) {   If ($LogErrors.Count -EQ 1) {     $errors = "Error" }   else {      $errors = "Errors"}   Write-Output "$($LogErrors.Count) $logName $errors found since $($lastWeek.ToString('D'))."}